  emberGeo.setAttribute('position', new THREE.BufferAttribute(emberPos, 3));
  const embers = new THREE.Points(
    emberGeo,
    new THREE.PointsMaterial({ color: 0xff7a2e, size: 0.055, transparent: true, opacity: 0.85, depthWrite: false, blending: THREE.AdditiveBlending })
  );
  scene.add(embers);

  // Ground fog sheets (very subtle)
  const fogMat = new THREE.MeshBasicMaterial({ map: smokeTexture, color: 0x9aa6a0, transparent: true, opacity: 0.035, depthWrite: false, side: THREE.DoubleSide });
  for (let i = 0; i < 5; i++) {
    const fog = new THREE.Mesh(new THREE.PlaneGeometry(22, 12), fogMat.clone());
    fog.rotation.x = -Math.PI / 2;
    fog.position.set(-28 + rand() * 56, 0.25, -24 + rand() * 48);
    fog.rotation.z = rand() * 3;
    scene.add(fog);
  }

  // ---------------------------------------------------------------- SPAWN POINTS
  const spawnPoints = [
    { x: 0, z: 33.5 }, { x: -33.5, z: 28.5 }, { x: 33, z: 27 },
    { x: -34.6, z: 0 }, { x: 34.5, z: -3 }, { x: -30, z: -31 },
    { x: 30, z: -31.5 }, { x: 0, z: -33 }, { x: 17, z: 33 },
    { x: -16, z: 33 }, { x: -34, z: -20 }, { x: 34, z: -23 },
  ].filter((p) => !colliders.some((c) => p.x > c.minX - 0.8 && p.x < c.maxX + 0.8 && p.z > c.minZ - 0.8 && p.z < c.maxZ + 0.8));

  // ---------------------------------------------------------------- UPDATE
  let ashCursor = 0;
  function update(dt, time, playerPos) {
    for (const item of animated) item.update(time);
    for (const item of dynamicLights) {
      item.light.intensity = item.base * (0.92 + Math.sin(time * 7 + item.seed) * 0.04 + Math.sin(time * 13.7 + item.seed) * 0.025);
    }
    for (const item of fireLights) {
      item.light.intensity = 27 + Math.sin(time * 11 + item.seed) * 6 + Math.sin(time * 19.7 + item.seed) * 3;
      const s = 1.2 + Math.sin(time * 9 + item.seed) * 0.16;
      item.fire.scale.set(1.2 * s, 1.9 * s, 1);
      item.fire.material.opacity = 0.68 + Math.sin(time * 14 + item.seed) * 0.12;
    }
    for (const puff of smokePuffs) {
      puff.sprite.position.y += puff.speed * dt;
      puff.sprite.position.x += Math.sin(time * 0.3 + puff.phase) * dt * 0.16;
      const cycle = ((puff.sprite.position.y - puff.baseY) % 10 + 10) % 10;
      puff.sprite.material.opacity = Math.max(0, Math.sin((cycle / 10) * Math.PI) * 0.2);
      const scale = puff.baseScale * (0.7 + cycle * 0.085);
      puff.sprite.scale.set(scale, scale, 1);
    }
    // ash drifts and wraps around the play area
    const pos = ashGeo.attributes.position.array;
    for (let i = 0; i < ashCount; i++) {
      pos[i * 3 + 1] -= ashSpeed[i] * dt;
      pos[i * 3] += Math.sin(time * 0.22 + i) * dt * 0.1;
      if (pos[i * 3 + 1] < 0.1) {
        pos[i * 3 + 1] = 20 + rand() * 6;
        pos[i * 3] = playerPos.x + (rand() - 0.5) * 30;
        pos[i * 3 + 2] = playerPos.z + (rand() - 0.5) * 30;
      }
    }
    ashGeo.attributes.position.needsUpdate = true;

    const ePos = emberGeo.attributes.position.array;
    for (let i = 0; i < emberCount; i++) {
      ePos[i * 3 + 1] += (0.35 + (i % 5) * 0.07) * dt;
      ePos[i * 3] += Math.sin(time * 2.2 + emberPhase[i]) * dt * 0.15;
      if (ePos[i * 3 + 1] > 4.4) {
        ePos[i * 3 + 1] = 0.7;
        ePos[i * 3] = 4.1 + (rand() - 0.5) * 0.55;
        ePos[i * 3 + 2] = -12.8 + (rand() - 0.5) * 0.55;
      }
    }
    emberGeo.attributes.position.needsUpdate = true;
    ashCursor += dt;
  }

  return {
    colliders,
    occluders,
    spawnPoints,
    uplink,
    materials: mat,
    update,
  };
}

import * as THREE from '../vendor/three.module.min.js';

/* First-person weapon models, built from primitives. Origin of every model is
   the optical centerline so ADS lines up naturally with the camera. */

function flashTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 62);
  g.addColorStop(0, 'rgba(255,255,235,1)');
  g.addColorStop(0.16, 'rgba(255,238,170,0.98)');
  g.addColorStop(0.38, 'rgba(255,150,54,0.7)');
  g.addColorStop(0.7, 'rgba(255,90,20,0.18)');
  g.addColorStop(1, 'rgba(255,60,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  // Star flare
  ctx.save();
  ctx.translate(64, 64);
  for (let i = 0; i < 6; i++) {
    ctx.rotate(Math.PI / 3);
    ctx.fillStyle = 'rgba(255,224,160,0.34)';
    ctx.beginPath();
    ctx.moveTo(-4, 0);
    ctx.lineTo(0, -61);
    ctx.lineTo(4, 0);
    ctx.closePath();
    ctx.fill();
  }
  ctx.restore();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function makeMaterials() {
  return {
    metal: new THREE.MeshStandardMaterial({ color: 0x262b2b, roughness: 0.36, metalness: 0.78 }),
    metalDark: new THREE.MeshStandardMaterial({ color: 0x101414, roughness: 0.4, metalness: 0.72 }),
    polymer: new THREE.MeshStandardMaterial({ color: 0x2c302b, roughness: 0.72, metalness: 0.14 }),
    tan: new THREE.MeshStandardMaterial({ color: 0x6b624b, roughness: 0.8, metalness: 0.08 }),
    glove: new THREE.MeshStandardMaterial({ color: 0x23251f, roughness: 0.92 }),
    sleeve: new THREE.MeshStandardMaterial({ color: 0x3b4035, roughness: 0.92 }),
    accent: new THREE.MeshStandardMaterial({ color: 0x9a7b3c, roughness: 0.65, metalness: 0.3 }),
    glass: new THREE.MeshStandardMaterial({ color: 0x1c3330, roughness: 0.08, metalness: 0.5, transparent: true, opacity: 0.35, side: THREE.DoubleSide }),
    dot: new THREE.MeshBasicMaterial({ color: 0xff3d24 }),
  };
}

function box(group, mat, w, h, d, x, y, z, rx = 0, ry = 0, rz = 0) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  mesh.position.set(x, y, z);
  mesh.rotation.set(rx, ry, rz);
  group.add(mesh);
  return mesh;
}

function cylinder(group, mat, radius, length, x, y, z, axis = 'z') {
  const geo = new THREE.CylinderGeometry(radius, radius, length, 10);
  if (axis === 'z') geo.rotateX(Math.PI / 2);
  if (axis === 'x') geo.rotateZ(Math.PI / 2);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(x, y, z);
  group.add(mesh);
  return mesh;
}

function buildFlash(size = 0.34) {
  const texture = flashTexture();
  const group = new THREE.Group();
  const mat = new THREE.SpriteMaterial({ map: texture, color: 0xffd9a1, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.set(size, size, 1);
  group.add(sprite);
  const sprite2 = new THREE.Sprite(mat.clone());
  sprite2.material.opacity = 0;
  sprite2.scale.set(size * 0.6, size * 1.1, 1);
  sprite2.material.rotation = 0.6;
  group.add(sprite2);
  const light = new THREE.PointLight(0xffb463, 0, 6, 2);
  group.add(light);
  group.visible = false;
  return { group, sprite, sprite2, mat: sprite.material, mat2: sprite2.material, light, life: 0 };
}

function buildRifle(M) {
  const g = new THREE.Group();
  g.name = 'M4_CARBINE';

  // Receiver
  box(g, M.metal, 0.12, 0.135, 0.56, 0, -0.092, -0.08);
