  const dotGlow = new THREE.Sprite(new THREE.SpriteMaterial({ color: 0xff2d18, transparent: true, opacity: 0.6, blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false }));
  dotGlow.position.copy(dot.position);
