export function createWeapons(camera) {
  const M = makeMaterials();
  const root = new THREE.Group();
  root.name = 'viewmodel';
  root.renderOrder = 999;
  camera.add(root);

  const camLight = new THREE.PointLight(0xffd9b0, 0.9, 2.4, 2);
  camLight.position.set(0.15, 0.1, 0.1);
  camera.add(camLight);

  const rifle = buildRifle(M);
  const pistol = buildPistol(M);
  root.add(rifle.group, pistol.group);
  pistol.group.visible = false;

  const weapons = {
    rifle: {
      ...rifle,
      id: 'rifle',
      name: 'M4 CARBINE',
      className: 'ASSAULT RIFLE',
      fireMode: 'AUTO',
      magSize: 30,
      maxReserve: 300,
      reserve: 210,
      ammo: 30,
      damage: 34,
      headMult: 2.35,
      rpm: 720,
      auto: true,
      reloadTime: 2.05,
      hipSpread: 0.014,
      adsSpread: 0.0022,
      recoil: 0.0046,
      recoilYaw: 0.0018,
      sound: 'rifle',
      tracerColor: 0xffd8a4,
      adsFov: 50,
    },
    pistol: {
      ...pistol,
      id: 'pistol',
      name: 'P226 SIDEARM',
      className: 'SIDEARM',
      fireMode: 'SEMI',
      magSize: 12,
      maxReserve: 84,
      reserve: 48,
      ammo: 12,
      damage: 54,
      headMult: 2.4,
      rpm: 320,
      auto: false,
      reloadTime: 1.45,
      hipSpread: 0.01,
      adsSpread: 0.0016,
      recoil: 0.0065,
      recoilYaw: 0.0025,
      sound: 'pistol',
      tracerColor: 0xffedba,
      adsFov: 56,
    },
  };

  root.position.copy(weapons.rifle.hipPos);

  return {
    root,
    weapons,
    materials: M,
    show(id) {
      Object.values(weapons).forEach((w) => {
        w.group.visible = w.id === id;
      });
    },
    updateFlash(weapon, dt) {
      const f = weapon.flash;
      if (!f) return;
      if (f.life > 0) {
        f.life -= dt;
        const p = Math.max(0, f.life / 0.055);
        f.group.visible = p > 0;
        f.mat.opacity = p * 0.95;
        f.mat2.opacity = p * 0.65;
        f.light.intensity = p * 14;
        f.sprite.material.rotation = Math.random() * Math.PI;
        f.sprite2.material.rotation = Math.random() * Math.PI;
      } else {
        f.group.visible = false;
        f.light.intensity = 0;
        f.mat.opacity = 0;
        f.mat2.opacity = 0;
      }
    },
    triggerFlash(weapon) {
      weapon.flash.life = 0.055;
      weapon.flash.group.visible = true;
    },
  };
}

