+    rotX += 0.11;
+    rotY += 0.45;
+    rotZ += 0.15;
+  }
+  weaponSystem.root.rotation.set(rotX, rotY, rotZ);
+
+  // FOV breathing
+  const targetFov = ads > 0.55 ? w.adsFov : player.sprinting ? 80 : 73;
