+  camera.updateProjectionMatrix();
+
+  // Crosshair expansion
+  const moveFactor = clamp(player.speed / 7, 0, 1);
+  const gap = 5 + (1 - ads) * 8 + moveFactor * 5 + weaponState.kick * 4;
