+
+  if (weaponState.reloading) ui.reloadState.textContent = 'RELOADING';
+  else if (weaponState.current.ammo === 0) ui.reloadState.textContent = 'MAG EMPTY';
+  else ui.reloadState.textContent = '';
+
+  player.mouseDX = 0;
+  player.mouseDY = 0;
+}
