+    return;
+  }
+
+  let f = 0;
+  let s = 0;
+  if (keys.has('KeyW')) f += 1;
+  if (keys.has('KeyS')) f -= 1;
+  if (keys.has('KeyD')) s += 1;
+  if (keys.has('KeyA')) s -= 1;
+  f += input.touchMoveY;
+  s += input.touchMoveX;
+  const mag = Math.hypot(f, s);
+  if (mag > 1) {
+    f /= mag;
+    s /= mag;
+  }
+  const moving = mag > 0.08;
