// ---------------------------------------------------------------- MISSION FLOW
function clearBattle() {
  for (const e of enemies) {
    scene.remove(e.group);
    e.mats.forEach((m) => m.dispose());
    scene.remove(e.healthBar.group);
    e.healthBar.bgMat.dispose();
    e.healthBar.fillMat.dispose();
  }
