import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright/index.mjs';

const browser = await chromium.launch({
  args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--autoplay-policy=no-user-gesture-required'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });

const logs = [];
page.on('console', (m) => { if (m.type() === 'error' || m.type() === 'warning') logs.push(`[${m.type()}] ${m.text()}`); });
page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
page.on('requestfailed', (r) => logs.push(`[requestfailed] ${r.url()} ${r.failure()?.errorText}`));
page.on('response', (r) => { if (r.status() >= 400) logs.push(`[http ${r.status()}] ${r.url()}`); });

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.waitForTimeout(2500);

const menuVisible = await page.locator('#menuScreen, .menu-screen').first().isVisible().catch(() => null);
console.log('menu visible:', menuVisible);
await page.screenshot({ path: '/tmp/opencode/final-menu.png' });

// start mission via Enter
await page.keyboard.press('Enter');
await page.waitForTimeout(3000);

const state1 = await page.evaluate(() => ({
  mode: window.brokenLine.game.mode,
  phase: window.brokenLine.game.phase,
  wave: window.brokenLine.game.wave,
  health: window.brokenLine.game.health,
  ammo: window.brokenLine.game.weapon?.ammo ?? null,
  hudHidden: document.getElementById('hud')?.classList.contains('hidden'),
  enemyCount: window.brokenLine.enemies.length,
}));
console.log('after deploy:', JSON.stringify(state1));
await page.screenshot({ path: '/tmp/opencode/final-game.png' });

// fire
await page.mouse.move(720, 450);
await page.mouse.down();
await page.waitForTimeout(900);
await page.mouse.up();
await page.waitForTimeout(300);
const afterFire = await page.evaluate(() => ({
  ammo: window.brokenLine.game.weapon?.ammo ?? null,
  reserve: window.brokenLine.game.weapon?.reserve ?? null,
}));
console.log('after fire:', JSON.stringify(afterFire));

// reload
await page.keyboard.press('KeyR');
await page.waitForTimeout(2200);
console.log('after reload:', JSON.stringify(await page.evaluate(() => ({ ammo: window.brokenLine.game.weapon?.ammo, reloading: window.brokenLine.game.reloading }))));

// pause
await page.keyboard.press('Escape');
await page.waitForTimeout(600);
console.log('after pause:', JSON.stringify(await page.evaluate(() => ({ mode: window.brokenLine.game.mode, paused: window.brokenLine.game.paused }))));
await page.screenshot({ path: '/tmp/opencode/final-pause.png' });

// resume
await page.keyboard.press('Escape');
await page.waitForTimeout(600);
console.log('after resume:', JSON.stringify(await page.evaluate(() => ({ mode: window.brokenLine.game.mode, paused: window.brokenLine.game.paused }))));

// simulate some combat time
const sim = await page.evaluate(() => window.brokenLine.simulate(4));
console.log('simulate 4s:', JSON.stringify(sim));

// forced death flow
await page.evaluate(() => { window.brokenLine.game.health = 1; });
const death = await page.evaluate(() => {
  for (let i = 0; i < 40; i++) {
    window.brokenLine.simulate(0.25);
    if (window.brokenLine.game.phase === 'dead' || window.brokenLine.game.mode === 'over') break;
  }
  return { mode: window.brokenLine.game.mode, phase: window.brokenLine.game.phase, health: window.brokenLine.game.health };
});
console.log('death attempt:', JSON.stringify(death));
await page.waitForTimeout(800);
await page.screenshot({ path: '/tmp/opencode/final-death.png' });

console.log('--- console/network issues ---');
console.log(logs.length ? logs.join('\n') : 'none');

await browser.close();
